&-contact {
  $root: &;
  position: relative;
  height: auto;
  min-height: var(--scene-shell-span);

  .line {
    text-align: center;
  }

  &__stage {
    position: sticky;
    top: 0;
    z-index: 4;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: var(--gutter-lg);
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    text-align: center;
    transition:
      opacity var(--transition-default),
      transform var(--transition-default);
    transform: translate3d(0, 24px, 0);
  }

  &__stage > .no-container {
    width: 100%;
  }

  &__panel {
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    pointer-events: auto;
  }

  &[data-active="true"] {
    #{$root}__stage {
      opacity: 1;
      visibility: visible;
      transform: translate3d(0, 0, 0);
    }
  }

  &__head {
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--gutter-md);

    h2 {
      color: var(--clr-text-title);
    }

    p {
      margin-top: var(--gutter-md);
    }
  }

  &__actions {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--gutter-sm);
    margin-top: var(--gutter-xl);
  }

  &__action {
    margin-top: 0;
  }

  &__footer {
    position: relative;
    z-index: 1;
    margin-top: 0;
  }

  @include mq(md) {
    &__stage {
      padding-left: var(--gutter-lg);
      padding-right: var(--gutter-lg);
    }

    &__actions {
      flex-direction: column;
      width: 100%;
    }

    &__action {
      width: 100%;
    }

