    display: flex;
    flex-direction: column;
  }

  &__item {
    display: grid;
    grid-template-columns: 2fr 6fr 4fr;
    gap: var(--gutter-sm);
    align-items: center;
    padding: var(--gutter-2xl) 0;
    border-top: 1px solid rgba(255, 255, 255, 0.12);

    &:last-child {
      border-bottom: 1px solid rgba(255, 255, 255, 0.12);
    }

    @include mq(md) {
      grid-template-columns: 1fr;
      gap: var(--gutter-xs);
    }
  }

  &__item-title {
  }
  .no-services__num {
    color: rgba(255, 255, 255, 0.56);
    display: flex;
    align-items: center;
    min-height: fluid(16, 22);

    .no-loop-filter-rect {
      gap: 0;

      span {
        width: fluid(4, 6);
        height: fluid(4, 6);
      }
    }
  }
}

